contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint depAmount, uint collectAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depAmount)); require(depAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depAmount);
        require(depAmount > 0);
        require(collectAmount > 0);
        require(collectAmount <= depAmount);

        c.SetMinSum(0); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;
        c.Deposit{value: depAmount}(); if (__ESBMC_reverted()) return;

        uint balBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint minBefore = c.MinSum(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.Collect(collectAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        uint balAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint minAfter = c.MinSum(); if (__ESBMC_reverted()) return;

        assert(
            (reverted == (balBefore < minBefore || balBefore < collectAmount))
            && (minAfter == minBefore)
            && (reverted || balAfter == balBefore - collectAmount)
        );
    }

    receive() external payable {}
}

