contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function _run(uint256 depAmount, uint256 collectAmount) internal {
        depAmount = bound(depAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depAmount);
        vm.assume(depAmount > 0);
        vm.assume(collectAmount > 0);
        vm.assume(collectAmount <= depAmount);
        try c.SetMinSum(0) {} catch { return; }
        try c.Initialized() {} catch { return; }
        try c.Deposit{value: depAmount}() {} catch { return; }
        uint256 balBefore;
        try c.balances(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        uint256 minBefore;
        try c.MinSum() returns (uint256 __r) { minBefore = __r; } catch { return; }
        bool reverted;
        try c.Collect(collectAmount) { reverted = false; } catch { reverted = true; }
        uint256 balAfter;
        try c.balances(address(this)) returns (uint256 __r) { balAfter = __r; } catch { return; }
        uint256 minAfter;
        try c.MinSum() returns (uint256 __r) { minAfter = __r; } catch { return; }
        assertTrue((reverted == (balBefore < minBefore || balBefore < collectAmount))
            && (minAfter == minBefore)
            && (reverted || balAfter == balBefore - collectAmount));
    }

    function testFuzz_run(uint256 depAmount, uint256 collectAmount) public {
        _run(depAmount, collectAmount);
    }

    receive() external payable {}
